import{_ as l,l as r,o as a,c as d,v as o,p as n,x as t,d as c,i as E,S as s}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"数字切分","description":"","frontmatter":{"title":"数字切分","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/digit-splitting.md","filePath":"llm/digit-splitting.md","lastUpdated":1789023840000}'),p={name:"llm/digit-splitting.md"};function m(A,e,h,B,D,f){const i=r("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="数字切分" tabindex="-1">数字切分 <a class="header-anchor" href="#数字切分" aria-label="Permalink to &quot;数字切分&quot;">​</a></h1><div class="epigraph"><p>把每个数位收成单独的 token，算术任务才不必在「2024」有时是一块、有时是三块之间猜测对齐。</p><footer>—— 据 Nogueira, Jiang, Lin 对 Transformer 算术限制的讨论；对照 Llama 3 报告中的数位切分整理</footer></div><p><a href="/llm/byte-fallback">上一课</a>保证未见字符能拆成字节，数字本身却几乎总在词表里。<code>0</code>–<code>9</code> 作为字符或字节都覆盖得到，BPE 仍会按频率把 <code>19</code>、<code>202</code>、<code>000</code> 焊成不规则块。本课不重讲回退，也不重讲 <a href="/llm/bpe-merge-rule">BPE 合并</a> 的计数规则。缺口是：频率目标与「这是一个十进制整数」的任务目标不一致时，切分必须被显式约束。后课的特殊 token 默认数字已经按位切开或按固定粒度切开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/pretokenization-regex">预分词正则</a>若用 <code>\\p{N}+</code> 把连续数字收成一块，块内 BPE 会把高频年号、百分数、代码里的 <code>1024</code> 焊成若干碎片，且碎片边界随词表而变。<code>2024</code> 与 <code>2025</code> 可能共享 <code>202</code> 再各跟一个尾数，也可能完全不同。模型要做进位、比大小、抄写长数字时，对齐关系每次都在变。Nogueira 等人指出，即便是小学算术，切分方式也会让 Transformer 显得「不会算」——先修不是注意力公式，而是离散序列有没有把数位对齐。</p><p>纯字节回退帮不上忙：数字字符都在表内，根本不会落到 <code>&lt;0x3x&gt;</code>。需要一条独立规则：在合并之前或合并表里，禁止把数位焊成多位原子，或只允许固定宽度（如三位一组）的焊法。</p><h3 id="频率焊数是压缩-不是计数" tabindex="-1">频率焊数是压缩，不是计数 <a class="header-anchor" href="#频率焊数是压缩-不是计数" aria-label="Permalink to &quot;频率焊数是压缩，不是计数&quot;">​</a></h3><p>电话号、年份、金额、IP、超参里的 <code>3e-4</code>，在网页里极高频。BPE 把它们当成普通字母串压缩，是算法正确、任务错误。压缩率会略降，因为 <code>2024</code> 从 1 个 token 变成 4 个；上下文窗口里数字变贵。这是用长度换可组合的计数原语。</p><p><span class="marginnote">科学计数法、小数点、千分位逗号、全角数字，都不是「一个整数」。切分规则必须声明：只约束 ASCII 十进制数位，还是连 <code>\\p{N}</code> 的其他码点一起切。含糊的规则会在评测集上制造不可复现的分数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实践里常见三种约束。第一，预分词把每个 ASCII 数位切成单字符块，合并表根本看不见相邻数位对——Llama 3 一类 128k tiktoken 词表公开采用单数字切分。第二，允许固定块（每三位），迁就千分位阅读习惯，但对齐仍比纯频率焊好。第三，在已有 BPE 表上后处理：匹配到最长数字跨度后再强制按位切开，代价是与训练时切分必须一致，否则是另一种换词表。</p><p>训练新词表时，第一种最干净：正则里把 <code>\\p{N}+</code> 改成逐位，或在合并时把数位对的频次置零。不要指望「多喂数学语料」让频率自己焊出正确的数位原子——频率会焊出 <code>100</code>、<code>999</code> 这种块，而不是通用的进位结构。</p><h3 id="与-unigram-的关系" tabindex="-1">与 Unigram 的关系 <a class="header-anchor" href="#与-unigram-的关系" aria-label="Permalink to &quot;与 Unigram 的关系&quot;">​</a></h3><p><a href="/llm/unigram-segmentation">Unigram 切分</a>按似然挑分割，数字串上往往仍偏好整块，因为整块在词表里概率不低。要稳定的数位对齐，不能靠采样正则化，必须在候选词表里删掉多位数字符号，或给它们 −∞ 的 logit。子词正则化可以继续作用在字母上，数字路径保持确定。</p><p><span class="marginnote">代码里的十六进制 <code>0xff</code>、版本号 <code>1.2.3</code>、张量形状 <code>1024</code> 会同时变长。词表训练语料若含大量代码，应在 fertility 报表里单独列数字 token 占比，否则会误判「代码配比过高」。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>逐位切分让加法、比较在 token 网格上对齐到十进制位：个位总与个位相邻（中间或有分隔符）。嵌入只需要学 10 个数位符号的算术角色，而不是学一份「哪些多位块曾经一起出现」的查找表。Wallace 等人对 NLP 模型是否「理解数字」的探测，也依赖数字被表示成可组合的单元；焊死的多位块把探测变成记忆。</p><p>代价落在序列长度与位置编码上。同一上下文窗口能放下的数字变少；长表、账本、竞赛题更容易截断。这与长文档上采样是同一条账，只是本课先把切分固定下来。</p>',18)),(a(),n(s,null,{default:t(()=>[E(i,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20NUM%5B%22%E8%BF%9E%E7%BB%AD%E6%95%B0%E5%AD%97%E4%B8%B2%22%5D%20--%3E%20POL%7B%22%E5%88%87%E5%88%86%E7%AD%96%E7%95%A5%22%7D%0A%20%20POL%20--%3E%7C%22%E9%A2%91%E7%8E%87%20BPE%22%7C%20FRAG%5B%22%E4%B8%8D%E8%A7%84%E5%88%99%E5%A4%9A%E4%BD%8D%E5%9D%97%22%5D%0A%20%20POL%20--%3E%7C%22%E9%80%90%E4%BD%8D%22%7C%20DIG%5B%22%E5%8D%95%E6%95%B0%E5%AD%97%20token%22%5D%0A%20%20POL%20--%3E%7C%22%E5%9B%BA%E5%AE%9A%E5%AE%BD%E5%BA%A6%22%7C%20GRP%5B%22%E7%AD%89%E5%AE%BD%E6%95%B0%E5%AD%97%E7%BB%84%22%5D%0A%20%20DIG%20--%3E%20AR%5B%22%E5%AF%B9%E9%BD%90%E7%9A%84%E7%AE%97%E6%9C%AF%E7%BD%91%E6%A0%BC%22%5D%0A%20%20GRP%20--%3E%20AR%0A%20%20FRAG%20--%3E%20MEM%5B%22%E9%9D%A0%E8%AE%B0%E5%BF%86%E8%A1%A5%E8%BF%9B%E4%BD%8D%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>逐位切分不自动教会进位；它只提供对齐。小数、分数、不同进制仍要靠后续层。也不要在聊天模板里把用户 ID、时间戳按位切开却在工具调用的 JSON 里用另一套规则——特殊 token 课会要求控制符与正文切分隔离，数字规则必须两边一致。</p><p>若产品几乎不做算术、却大量抄写长 ID，逐位会浪费窗口。此时可对「看起来像标识符的数字」保留整块，但必须有可测试的判定，不能靠另一张小 BPE 表偷偷合并。默认预训练词表应在算术可组合与压缩之间取明确的一点，并写进词表卡片。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲字节回退；数字已在表内，缺的是禁止频率乱焊。</li><li>逐位切分让数位在序列上对齐，是算术任务的前置约束，不是额外数据能替代的。</li><li>Unigram 不会自动切对数字，候选里要删掉多位数字符号。</li><li>长度变贵；代码与表格的 fertility 会上升。</li><li>控制符与 JSON 必须共用同一数字规则。</li><li>出处：Nogueira, Jiang, Lin, 2021；Wallace et al., EMNLP 2019；Llama 3 技术报告中的 128k 词表与数位切分；Radford et al., GPT-2, 2019。</li></ul>',5))])}const g=l(p,[["render",m]]);export{_ as __pageData,g as default};
